 377	fn startSynchronizedOutput(self: *Thread, cb: *CallbackData) void {
 378	    self.sync_reset.reset(
 379	        &self.loop,
 380	        &self.sync_reset_c,
 381	        &self.sync_reset_cancel_c,
 382	        sync_reset_ms,
 383	        CallbackData,
 384	        cb,
 385	        syncResetCallback,
 386	    );
 387	}
